"""Derived report; inference, parser, comparisons and cohorts stay immutable."""
import csv
from common_g12 import *
def rate(x):return 'N/A' if x is None else f'{100*float(x):.2f}%'
def pp(x):return 'N/A' if x is None else f'{100*float(x):.2f} pp'
def table(rows,keys):return '|'+ '|'.join(keys)+'|\n|'+'|'.join(['---']*len(keys))+'|\n'+''.join('|'+ '|'.join(str(r.get(k,'')) for k in keys)+'|\n' for r in rows)
def rows(p):return list(csv.DictReader((ROOT/p).open()))
def main():
 stats=json.loads((ROOT/'evaluation/paired_statistics.json').read_text());means=stats['fixed_seed_means'];mainrows=rows('evaluation/main.csv');hist=rows('evaluation/history.csv');steps=rows('evaluation/per_step.csv');decision=json.loads((ROOT/'evaluation/decision.json').read_text());budget=json.loads((ROOT/'budget.json').read_text());audit=json.loads((ROOT/'audit.json').read_text());pre=json.loads((ROOT/'data/precheck.json').read_text())
 effects=[]
 for split in ['iid','template_ood']:
  for contrast in ['B-A/trajectory4','B-A/trajectory5','B-Original/trajectory5','B-A/atomic','B-Original/atomic']:
   r=next(r for r in means if r['split']==split and r['contrast']==contrast and r['cohort']=='all');effects.append(dict(split=split,contrast=contrast,mean=pp(r['mean_difference']),seed_range=f'{pp(r["min_seed"])} to {pp(r["max_seed"])}',CI95_pp=[None if v is None else round(100*v,2) for v in r['ci95']],positive_seeds=r['positive_seeds']))
 mi=next(r for r in means if r['split']=='iid' and r['contrast']=='B-A/trajectory5');mo=next(r for r in means if r['split']=='template_ood' and r['contrast']=='B-A/trajectory5')
 common_sizes=[int(r['AB_common_equal_mask']) for r in mainrows if r['method']=='A'];cohort_answer='A/B共同strict+equal-mask集合全部为空，历史差距变化不可估计；不能称差距已缩小。' if not any(common_sizes) else '历史差距变化只在下列A/B共同strict+equal-mask分母上解释，低覆盖组单列。'
 atomic_effects=[r for r in means if r['contrast'] in ['B-A/atomic','B-Original/atomic']];atomic_answer='原子保护不满足预定5pp范围，不能称可靠语义算子已恢复。' if any(r['mean_difference']<-.05 for r in atomic_effects) else '原子均值的5pp保护线满足；字段损坏和未决仍须单独查看。'
 headline=f'**B相对A没有提高第四/第五步完整轨迹：两组各seed、各split均0/80。第五步配对差IID {pp(mi["mean_difference"])}, OOD {pp(mo["mean_difference"])}。** {cohort_answer} {atomic_answer} 已解析输出存在数量损坏，第五步输出全部解析未决，不能确认全体事实保持。数值继续门槛全部满足={decision["all_predefined_numerical_gates_met"]}。下表使用全部80个新世界；共同cohort历史对照另列，不能用各模型不同筛选集合替代固定分母。第三步已监督，第四/第五步才是本轮未训练长度。'
 display=[]
 for r in mainrows:
  z=r.copy();z['single_step_world_mean']=rate(r['single_step_world_mean']);z['third_endpoint']=r['third_endpoint']+'/80';z['fourth_trajectory']=r['fourth_trajectory']+'/80';z['fifth_trajectory']=r['fifth_trajectory']+'/80';z['H0_all']=r['H0_all']+'/80';z['H2_all']=r['H2_all']+'/80';z['H0_common']=rate(r['H0_common']) if r['H0_common'] else 'N/A';z['H2_common']=rate(r['H2_common']) if r['H2_common'] else 'N/A';display.append(z)
 hd=[]
 for r in hist:
  if r['cohort'] in ['own_strict_equal_mask','AB_common_equal_mask','AB_common_prefix_clean','cross_seed_AB_common']:
   z=r.copy();z['next_rate']=rate(r['next_rate']) if r['next_rate'] else 'N/A';hd.append(z)
 mechanism=[]
 for r in means:
  if r['cohort']=='AB_common_equal_mask' and r['contrast'] in ['A/Delta2','B/Delta2','B-A/Delta2','B-A/H0','B-A/H2','B-Original/H2']:
   mechanism.append(dict(split=r['split'],contrast=r['contrast'],seed_N=r['seed_N'],mean=pp(r['mean_difference']),CI95_pp=[None if v is None else round(100*v,2) for v in r['ci95']]))
 training=[]
 for s in CFG['seeds']:
  for arm in ['A','B']:
   r=json.loads((ROOT/f'training/{arm}_seed{s}.json').read_text());training.append(dict(method=arm,seed=s,updates=r['updates'],parameters=r['parameters'],supervised_samples=3200,supervision_tokens=r['counts']['supervision_tokens'],stage_tokens=r['stage_token_counts'],encoder_sample_calls=r['counts']['encoder_sample_calls'],editor_sample_calls=r['counts']['operator_sample_calls'],decoder_sample_calls=r['counts']['decoder_sample_calls'],training_seconds=round(r['training_seconds'],2),peak_GPU_GB=round(r['peak_cuda_bytes']/1e9,3)))
 perstep=[]
 for r in steps:perstep.append(dict(r,endpoint=f'{r["endpoint_joint"]}/{r["N"]}',trajectory=f'{r["trajectory_joint"]}/{r["N"]}'))
 field=rows('evaluation/field_errors.csv');bad=[r for r in field if int(r['confirmed_error_observations'])];error_summary=[]
 for kind in ['current','next','chain','atomic']:
  for arm in CFG['methods']:
   sub=[r for r in field if r['kind']==kind and r['method']==arm];byfield={f:sum(int(r['confirmed_error_observations']) for r in sub if r['field']==f) for f in FIELDS+['perspective']};error_summary.append(dict(kind=kind,method=arm,field_errors={k:v for k,v in byfield.items() if v},unresolved_observations=sum(int(r['unresolved']) for r in sub if r['field']=='quantity'),observation_N=sum(int(r['observations']) for r in sub if r['field']=='quantity')))
 lines=['# G12: Matched Input-Source Training','',headline,'', '## 固定世界主表','',table(display,['method','seed','split','fixed_worlds','single_step_world_mean','third_endpoint','fourth_trajectory','fifth_trajectory','H0_all','H2_all','own_strict','AB_common','AB_common_equal_mask','H0_common','H2_common','nondate_errors','unresolved']), '单步保护分数是每世界7个合法自然输入offset的joint平均，再对80世界平均。H0/H2 all均为主锚点下一步成功n/80。末两列是next+chain+atomic的输出观察计数（每行1200个输出），不是独立世界数，错误字段可重叠；各路径/字段及正常终止详见原始表。所有世界recorded_plan、first-person；未决不算成功，也不是已确认事实错误。','', '## 四/五步配对效果与原子保护','',table(effects,['split','contrast','mean','seed_range','CI95_pp','positive_seeds']),'2000次world-cluster bootstrap，方法/seed/状态/步骤共享IID或OOD内抽样索引；不重采样seed。区间只反映世界抽样。Original只识别继续训练的收益，主对照始终B−A。','', '## 同当前文本的历史差距：共同分母','',table(mechanism,['split','contrast','seed_N','mean','CI95_pp']), 'Delta2=H0−H2；B−A/Delta2小于0才是差距缩小，且须与H0/H2绝对变化联合看，不能把H0退化当修复。以下同时给 own strict、A/B共同strict+equal mask、prefix-clean及跨seed敏感性分母。N<40只作低覆盖诊断，不补世界。','',table(hd,['method','seed','split','cohort','history','N','low_coverage','next_joint','next_rate','full_history_joint','date_errors','nondate_errors','unresolved','non_normal_end']), '', '## 1–5步原始结果','',table(perstep,['method','seed','split','step','N','endpoint','trajectory','date_errors','nondate_errors','unresolved','non_normal_end']), '首次失败步数见evaluation/first_failure.csv；0表示五步全对。单步逐offset保护见atomic_by_state.csv。','', '## 保真与未决','',table(error_summary,['kind','method','field_errors','unresolved_observations','observation_N']), '字段错误可重叠，已解析子集无错误不能等同于全体保真。数量、作者/主体/接收者、动作、状态、否定、归属、记录日期均逐项核对；人称固定first-person。所有逐输出分数及正常终止保留。人工label为空，本轮为结构化自动检查，尚无真人审核。','', '## 训练监督与实际计算','',table(training,['method','seed','updates','parameters','supervised_samples','supervision_tokens','stage_tokens','encoder_sample_calls','editor_sample_calls','decoder_sample_calls','training_seconds','peak_GPU_GB']), '两组独立加载各seed同一G10 checkpoint；optimizer均新建。阶段CE按该阶段batch有效token归一化，三阶段等权。两臂均在线编码y0和y2，无缓存；B的第三次输入为本组当前h2.detach()，不使用测试激活或teacher。每batch2encoder、3editor、3decoder调用，stage有效token完全一致。训练计算结构配对，隐藏状态轨迹不同；不声称严格等FLOPs。最终200步固定，不选最优test/dev链checkpoint。dev每50步仅作固定诊断。','', f'训练合法源 {pre["train_N"]} 世界，开发 {pre["dev_N"]} 世界，3200个固定出现；mask/日期/模板排除记录在training_exclusions.json。所有8个原训练模板保留。梯度smoke test确认第三项不回传h2、第三T仍有有限非零梯度、前两损失照常传播；backbone梯度为空且weights不变。','', '## 资源、审计与边界','',f'累计GPU分配 {budget["gpu_seconds"]} 秒（{budget["gpu_seconds"]/3600:.3f} GPU小时），上限14400秒；并发峰值 {audit["peak_concurrent_gpus"]}。每allocation1卡，训练数组0–2%2且每seed串行A/B，训练结束才开评估。加载、失败/重试和dev都计入；队列等待不计GPU，parent/task不与step重复累加。完整账本budget.json。',f'固定门槛：{json.dumps(decision,ensure_ascii=False)}','本批不追加方法、seed、长度或G13。更长训练轨迹上的局部修复不能叫普遍可组合规律；跨文本严格匹配只是表面/评分状态匹配，不保证所有隐藏语义相同。mask一致不代表语义token位置对齐。G11 crossover没有唯一部件归因，本实验也不作神经元或离开流形机制宣称。','', '## 冻结与复现','', 'data/lock.json记录训练前协议/配置/数据/日程/模型和评分依赖hash；cohort_lock在所有最终checkpoint固定、current-only inference完成后先锁定，再执行任何next/long-chain。80+80新世界与全部可获得旧世界完整事实键及规范化render文本无重叠；数据选择只依语法/tokenizer。恢复文件在local/仅本地；公开六个小editor，基础模型及activation不上传。原始输出含目标/实际文本、frame、评分、mask、终止、耗时和模型hash。','README.md与commands.log给出入口。review/blind_cases.csv及CASES.md覆盖输出前抽取的20世界，方法映射独立保存。所有未决和失败保留原分母；没有真人审核。']
 observations=[]
 for split in ['iid','template_ood']:
  for a in CFG['methods']:
   rs=[r for r in mainrows if r['method']==a and r['split']==split];observations.append(dict(method=a,split=split,atomic_mean=rate(sum(float(r['single_step_world_mean']) for r in rs)/3),atomic_range=f'{rate(min(float(r["single_step_world_mean"]) for r in rs))} to {rate(max(float(r["single_step_world_mean"]) for r in rs))}',third_endpoint=rate(sum(int(r['third_endpoint']) for r in rs)/240),third_trajectory=rate(sum(int(r['trajectory_joint']) for r in steps if r['method']==a and r['split']==split and r['step']=='3')/240),fourth_trajectory=rate(sum(int(r['fourth_trajectory']) for r in rs)/240),fifth_trajectory=rate(sum(int(r['fifth_trajectory']) for r in rs)/240)))
 i=lines.index('## 固定世界主表');lines[i:i]=['## 直接回答与固定seed概览','',table(observations,['method','split','atomic_mean','atomic_range','third_endpoint','third_trajectory','fourth_trajectory','fifth_trajectory']), '直接测量：B的受监督第三步终点在IID全对、OOD三seed均值99.58%，A的纯表示第三步均未通过；但B的OOD seed42在第二步只有62/80正确，所以该seed第三步完整轨迹只有77.50%，不是100%。所有组四/五步完整轨迹均为0；Original seed44 IID第四步有1个终点正确，但此前已失败，不算完整轨迹成功。','', '输入来源对照支持的局部解释：在相同目标/监督/初始化预算下，edited-input监督更能修复实际第三步表示输入；本批没有未训练四/五步延伸证据，并伴随明显的自然输入原子能力代价。它不证明容量必然受限，也不证明获得了可组合规则。','', '机制分析受阻：A/B全部seed/split的strict cohort及共同交集为0。其自然编码today的单次编辑没有输出正确yesterday，主要停留在today；与从tomorrow连续两次编辑得到正确yesterday并存。全部下一步仍已生成，不能因cohort为空删除失败。在全分母中，B seed43/44的canonical yesterday下一步也为0，而H2下一步接近100%；这种H0退化不能包装成历史差距修复。','', '决策：没有达到预定继续信号。本固定方案只显示受监督第三步局部修复，第四步即再次失败，且单步明显受损；结束本批，不追加G13或继续加长监督追分。','']
 i=lines.index('## 同当前文本的历史差距：共同分母');lines[i:i]=['Original在本批7个自然输入offset上并非所有seed都满分：IID seed44保护为92.50%，OOD约88.93–90.36%。这些是新的固定状态全覆盖分数，不能拿旧不同视图分母上的G10单步分数代替。A/B相对同新集Original的下降已在配对表中计算。','']
 (ROOT/'REPORT.md').write_text('\n'.join(lines).rstrip()+'\n');print('G12 report written')
if __name__=='__main__':main()
